begin;
create schema if not exists pakupai;
revoke all on schema pakupai from public, anon, authenticated;
create table pakupai.room_config(singleton boolean primary key default true check(singleton),owner_id text not null,room_id text not null,room_name text not null,auth_salt text,auth_hash text,signing_secret text not null,seq bigint not null default 0,library_auth text,library_rev bigint not null default 0);
create table pakupai.agents(id text primary key,owner_id text not null,room_id text not null,invite_id text,name text not null,role text,status text not null check(status in ('pending','approved','revoked','declined')),key_hash text not null unique,created_at bigint not null,approved_at bigint,last_seen bigint,revoked_at bigint);
create table pakupai.invites(id text primary key,owner_id text not null,room_id text not null,token_hash text unique not null,label text,created_at bigint not null,expires_at bigint not null,used_at bigint,revoked_at bigint);
create table pakupai.events(id bigint primary key,agent_id text,kind text not null,text text not null,ts bigint not null);
create index events_agent_ts on pakupai.events(agent_id,ts);
create table pakupai.login_attempts(scope text not null,ip_hash text not null,ts bigint not null);
create index login_attempts_lookup on pakupai.login_attempts(scope,ip_hash,ts);
create table pakupai.files(id text primary key,name text not null,description text,body text not null,updated bigint);
create table pakupai.versions(file_id text not null,position integer not null,payload jsonb not null,primary key(file_id,position));
create table pakupai.bundles(id text primary key,name text not null);
create table pakupai.bundle_files(bundle_id text references pakupai.bundles(id) on delete cascade,file_id text references pakupai.files(id) on delete cascade,position integer not null,primary key(bundle_id,file_id));
create table pakupai.library_agents(id text primary key,payload jsonb not null);
create table pakupai.library_links(token text primary key,type text not null,ref text not null);
create table pakupai.room_bundles(agent_id text primary key,bundle_id text not null);
do $$declare t record;begin for t in select tablename from pg_tables where schemaname='pakupai' loop execute format('alter table pakupai.%I enable row level security',t.tablename);end loop;end$$;
create function pakupai.library_state() returns jsonb language sql set search_path='' as $$
select jsonb_build_object('rev',c.library_rev,'files',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'desc',description,'body',body,'updated',updated) order by id) from pakupai.files),'[]'::jsonb),'versions',coalesce((select jsonb_object_agg(file_id,v) from (select file_id,jsonb_agg(payload order by position) v from pakupai.versions group by file_id) a),'{}'::jsonb),'bundles',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'name',b.name,'fileIds',coalesce((select jsonb_agg(file_id order by position) from pakupai.bundle_files where bundle_id=b.id),'[]'::jsonb))) from pakupai.bundles b),'[]'::jsonb),'agents',coalesce((select jsonb_agg(payload) from pakupai.library_agents),'[]'::jsonb),'links',coalesce((select jsonb_agg(to_jsonb(l)) from pakupai.library_links l),'[]'::jsonb),'roomAgents',coalesce((select jsonb_object_agg(agent_id,bundle_id) from pakupai.room_bundles),'{}'::jsonb)) from pakupai.room_config c where singleton
$$;
create function pakupai.add_event(a text,k text,t text) returns bigint language plpgsql set search_path='' as $$declare n bigint;begin update pakupai.room_config set seq=seq+1 where singleton returning seq into n;insert into pakupai.events values(n,a,k,t,(extract(epoch from clock_timestamp())*1000)::bigint);delete from pakupai.events where id <= n-1000;return n;end$$;
create function public.pakupai_rpc(op text,args jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare c pakupai.room_config; a pakupai.agents; i pakupai.invites; t bigint:=(extract(epoch from clock_timestamp())*1000)::bigint; x jsonb; y jsonb; n integer; res jsonb;
begin
 if op='health' then return jsonb_build_object('ok',exists(select 1 from pakupai.room_config));end if;
 select * into c from pakupai.room_config where singleton;
 if op='context' then return jsonb_build_object('owner',jsonb_build_object('id',c.owner_id),'room',jsonb_build_object('id',c.room_id,'name',c.room_name),'auth',jsonb_build_object('salt',c.auth_salt,'hash',c.auth_hash),'secret',c.signing_secret,'library_auth',c.library_auth);end if;
 if op='agent_auth' then select * into a from pakupai.agents where key_hash=args->>'hash';if not found then return null;end if;return to_jsonb(a);end if;
 if op='owner_state' then return jsonb_build_object('room',jsonb_build_object('id',c.room_id,'name',c.room_name),'agents',coalesce((select jsonb_agg(to_jsonb(g)-'key_hash'-'owner_id'-'room_id'-'invite_id') from pakupai.agents g),'[]'::jsonb),'invites',coalesce((select jsonb_agg(v) from (select to_jsonb(z)-'token_hash'-'owner_id'-'room_id' v from pakupai.invites z order by created_at desc limit 30) q),'[]'::jsonb),'events',coalesce((select jsonb_agg(v order by id) from (select e.id,to_jsonb(e)||jsonb_build_object('agent',g.name) v from pakupai.events e left join pakupai.agents g on e.agent_id=g.id where e.id>coalesce((args->>'after')::bigint,0) order by e.id desc limit 200) q),'[]'::jsonb),'now',t);end if;
 if op='messages' then select * into a from pakupai.agents where id=args->>'id';if a.status<>'approved' then return jsonb_build_object('error','not_approved');end if;update pakupai.agents set last_seen=t where id=a.id and coalesce(last_seen,0)<t-30000;select coalesce(jsonb_agg(v order by id),'[]'::jsonb) into res from(select e.id,jsonb_build_object('id',e.id,'from',case when kind='owner' then 'owner' else coalesce(g.name,'agent') end,'self',e.agent_id=a.id,'text',e.text,'ts',e.ts) v from pakupai.events e left join pakupai.agents g on e.agent_id=g.id where e.id>coalesce((args->>'after')::bigint,0) and e.kind in ('owner','msg') order by e.id limit 100)q;return jsonb_build_object('messages',res,'next_after',coalesce((res->-1->>'id')::bigint,(args->>'after')::bigint,0));end if;
 if op='touch' then update pakupai.agents set last_seen=t where id=args->>'id' and coalesce(last_seen,0)<t-30000;return '{}'::jsonb;end if;
 if op='login_check' then delete from pakupai.login_attempts where ts<t-900000;select count(*) into n from pakupai.login_attempts where scope=args->>'scope' and ip_hash=args->>'ip' and ts>t-600000;return jsonb_build_object('blocked',n>=8);end if;
 if op='login_fail' then insert into pakupai.login_attempts values(args->>'scope',args->>'ip',t);return '{}'::jsonb;end if;
 if op='library_get' then return jsonb_build_object('state',pakupai.library_state());end if;
 if op='library_link' then select to_jsonb(l) into res from pakupai.library_links l where token=args->>'token';if res is null then return '{}'::jsonb;end if;return jsonb_build_object('link',res,'state',pakupai.library_state());end if;
 -- All writes lock this room, preserving rate limits, invitation use, event sequence and library revisions transactionally.
 select * into c from pakupai.room_config where singleton for update;
 if op='invite' then insert into pakupai.invites values(args->>'id',c.owner_id,c.room_id,args->>'hash',args->>'label',t,t+(args->>'hours')::bigint*3600000,null,null);delete from pakupai.invites where id in(select id from pakupai.invites order by created_at desc offset 200);return jsonb_build_object('ok',true);end if;
 if op='join' then select * into i from pakupai.invites where token_hash=args->>'invite_hash' and used_at is null and revoked_at is null and expires_at>t for update;if not found then return jsonb_build_object('error','invite_invalid_expired_or_used');end if;update pakupai.invites set used_at=t where id=i.id;insert into pakupai.agents(id,owner_id,room_id,invite_id,name,role,status,key_hash,created_at) values(args->>'id',c.owner_id,c.room_id,i.id,args->>'name',args->>'role','pending',args->>'key_hash',t);perform pakupai.add_event(args->>'id','request',(args->>'name')||' wants to join');return jsonb_build_object('ok',true);end if;
 if op='revoke_invite' then update pakupai.invites set revoked_at=t where id=args->>'id' and used_at is null and revoked_at is null;return jsonb_build_object('ok',found);end if;
 if op='transition' then select * into a from pakupai.agents where id=args->>'id';if not found then return jsonb_build_object('error','not_found');end if;if args->>'action'='approve' and a.status='pending' then update pakupai.agents set status='approved',approved_at=t where id=a.id;perform pakupai.add_event(a.id,'sys',a.name||' joined the room');elsif args->>'action'='decline' and a.status='pending' then update pakupai.agents set status='declined' where id=a.id;perform pakupai.add_event(a.id,'sys',a.name||' was declined');elsif args->>'action'='revoke' and a.status<>'revoked' then update pakupai.agents set status='revoked',revoked_at=t where id=a.id;perform pakupai.add_event(a.id,'sys',a.name||' was removed');else return jsonb_build_object('error','invalid_transition');end if;return jsonb_build_object('ok',true);end if;
 if op='post' then if args->>'id' is not null then select * into a from pakupai.agents where id=args->>'id';if a.status<>'approved' then return jsonb_build_object('error','not_approved');end if;select count(*) into n from pakupai.events where agent_id=a.id and ts>t-60000;if n>=30 then return jsonb_build_object('error','rate_limited');end if;update pakupai.agents set last_seen=t where id=a.id;end if;perform pakupai.add_event(args->>'id',case when args->>'id' is null then 'owner' else 'msg' end,args->>'text');return jsonb_build_object('ok',true);end if;
 if op='library_save' then
 x:=args->'state';if c.library_rev<>coalesce((x->>'rev')::bigint,0) then return jsonb_build_object('error','conflict');end if;
 delete from pakupai.bundle_files where bundle_id not in(select value->>'id' from jsonb_array_elements(x->'bundles')) or file_id not in(select value->>'id' from jsonb_array_elements(x->'files'));delete from pakupai.bundles where id not in(select value->>'id' from jsonb_array_elements(x->'bundles'));delete from pakupai.versions;delete from pakupai.files where id not in(select value->>'id' from jsonb_array_elements(x->'files'));delete from pakupai.library_agents where id not in(select value->>'id' from jsonb_array_elements(coalesce(x->'agents','[]'::jsonb)));delete from pakupai.library_links where token not in(select value->>'token' from jsonb_array_elements(coalesce(x->'links','[]'::jsonb)));delete from pakupai.room_bundles;
 for y in select value from jsonb_array_elements(x->'files') loop insert into pakupai.files values(y->>'id',y->>'name',y->>'desc',y->>'body',(y->>'updated')::bigint) on conflict(id) do update set name=excluded.name,description=excluded.description,body=excluded.body,updated=excluded.updated where (pakupai.files.name,pakupai.files.description,pakupai.files.body,pakupai.files.updated) is distinct from (excluded.name,excluded.description,excluded.body,excluded.updated);end loop;
 for y in select value from jsonb_array_elements(coalesce(x->'bundles','[]'::jsonb)) loop insert into pakupai.bundles values(y->>'id',y->>'name') on conflict(id) do update set name=excluded.name where pakupai.bundles.name is distinct from excluded.name;delete from pakupai.bundle_files where bundle_id=y->>'id' and file_id not in(select value #>> '{}' from jsonb_array_elements(y->'fileIds'));insert into pakupai.bundle_files select y->>'id',v #>> '{}',ord::integer from jsonb_array_elements(y->'fileIds') with ordinality as f(v,ord) on conflict(bundle_id,file_id) do update set position=excluded.position where pakupai.bundle_files.position is distinct from excluded.position;end loop;
 insert into pakupai.versions select key,v,body from jsonb_each(coalesce(x->'versions','{}'::jsonb)) vv cross join lateral jsonb_array_elements(vv.value) with ordinality f(body,v);
 for y in select value from jsonb_array_elements(coalesce(x->'agents','[]'::jsonb)) loop insert into pakupai.library_agents values(y->>'id',y) on conflict(id) do update set payload=excluded.payload where pakupai.library_agents.payload is distinct from excluded.payload;end loop;
 for y in select value from jsonb_array_elements(coalesce(x->'links','[]'::jsonb)) loop insert into pakupai.library_links values(y->>'token',y->>'type',y->>'ref') on conflict(token) do update set type=excluded.type,ref=excluded.ref where (pakupai.library_links.type,pakupai.library_links.ref) is distinct from (excluded.type,excluded.ref);end loop;
 insert into pakupai.room_bundles select key,value from jsonb_each_text(coalesce(x->'roomAgents','{}'::jsonb));
 update pakupai.room_config set library_rev=library_rev+1 where singleton returning library_rev into n;return jsonb_build_object('ok',true,'rev',n);
 end if;
 return jsonb_build_object('error','unknown_operation');
end$$;
revoke all on function public.pakupai_rpc(text,jsonb) from public,anon,authenticated;
grant execute on function public.pakupai_rpc(text,jsonb) to service_role;
revoke all on all tables in schema pakupai from public,anon,authenticated;
revoke all on all functions in schema pakupai from public,anon,authenticated;
commit;
